import{z as d,x as A,o as e,c as B,q as E,j as n,D as t,d as l,s as r,S as o}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"上下文 bandit","description":"","frontmatter":{"title":"上下文 bandit","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/contextual-bandits.md","filePath":"llm/contextual-bandits.md","lastUpdated":1791063341000}'),s={name:"llm/contextual-bandits.md"};function p(m,a,b,h,C,f){const i=A("Mermaid");return e(),B("div",null,[a[2]||(a[2]=E('<h1 id="上下文-bandit" tabindex="-1">上下文 bandit <a class="header-anchor" href="#上下文-bandit" aria-label="Permalink to &quot;上下文 bandit&quot;">​</a></h1><div class="epigraph"><p>上下文 bandit 是把 MDP 的时间维砍掉之后剩下的东西：看一眼情境，选一次动作，拿一拍奖励，回合当场结束。</p><footer>—— 据 Sutton 与 Barto, Reinforcement Learning: An Introduction, 2018 第 2 章；Auer 2002 整理</footer></div><p><a href="/llm/ppo-clip-view">上一课</a>用信任域语言重读了 PPO 的 clip：把比率裁剪读成近似信赖域，并把 <a href="/llm/grpo">GRPO</a> 放成无价值函数的折中。策略梯度这条线至此有了完整骨架，但它处处默认动作有长期后果。本课转入本单元的第一件最小案例：上下文 bandit——把时间维整个砍掉，看课程的哪些机制随之消失，哪些仍然留下。缺口不是简化，而是把「现在选什么」与「之后发生什么」分开，才能说清 LLM 后训练里哪些问题其实只有 bandit 那么大。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>从 <a href="/llm/mdp-five-tuple">MDP 五元组</a>起，本课程的困难都来自一件事：现在的动作改变以后的状态。价值函数为动作记账，贝尔曼方程让跨时间的账自洽，优势函数把功劳从回报里拆回 token，自举（<a href="/llm/td-zero-bootstrapping">TD(0) 与自举</a>）用下一状态的估计换方差。若动作不改变后继状态、回合在选出动作的瞬间结束，这层机制还剩多少？问题反着问更锋利：RLHF 里一次「prompt—完成—打分」到底用到了多少时间结构——如果没用上，为它付出的方差与偏差就是白付。</p><h3 id="回合只有一拍" tabindex="-1">回合只有一拍 <a class="header-anchor" href="#回合只有一拍" aria-label="Permalink to &quot;回合只有一拍&quot;">​</a></h3><p>上下文 bandit 的定义三行就写完：情境 \\(x\\sim d(x)\\)，动作 \\(a\\sim\\pi(\\cdot\\mid x)\\)，奖励 \\(r\\sim R(\\cdot\\mid x,a)\\)，然后回合结束。目标 \\(J(\\pi)=\\mathbb{E}_{x,a}[r]\\)。它是 MDP 的特例：视界为 1，转移算子退化，折扣 \\(\\gamma\\) 无处安放。策略梯度定理在这里退化成单项式</p> \\[\\nabla_\\theta J=\\mathbb{E}_{x,a}\\big[(r-b(x))\\,\\nabla_\\theta\\log\\pi(a\\mid x)\\big], \\]<p>没有对时间的求和，没有信用分配链，基线只需逐情境给 \\(b(x)\\)。动作价值 \\(Q(x,a)=\\mathbb{E}[r\\mid x,a]\\) 可以直接从数据平均出来，不必自举——<a href="/llm/deadly-triad">致命三要素</a>里「自举」那一角直接消失。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2>',10)),(e(),n(o,null,{default:t(()=>[r(i,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E6%83%85%E5%A2%83%20x%EF%BC%88prompt%EF%BC%89%22%5D%20--%3E%20PI%5B%22%E7%AD%96%E7%95%A5%20%CF%80%20%E9%80%89%E5%8A%A8%E4%BD%9C%20a%EF%BC%88%E6%95%B4%E6%9D%A1%E5%AE%8C%E6%88%90%EF%BC%89%22%5D%0A%20%20PI%20--%3E%20R%5B%22%E5%A5%96%E5%8A%B1%20r%EF%BC%88%E6%A0%87%E9%87%8F%E6%89%93%E5%88%86%EF%BC%89%22%5D%0A%20%20R%20--%3E%20E%5B%22%E5%9B%9E%E5%90%88%E7%BB%93%E6%9D%9F%EF%BC%9A%E6%97%A0%E5%90%8E%E7%BB%A7%E7%8A%B6%E6%80%81%22%5D%0A%20%20R%20--%3E%20ALT%5B%22%E8%8B%A5%20a%20%E8%BF%98%E5%86%B3%E5%AE%9A%E5%90%8E%E7%BB%A7%20s%E2%80%B2%22%5D%0A%20%20ALT%20--%3E%20FULL%5B%22%E5%9B%9E%E5%88%B0%E5%AE%8C%E6%95%B4%20RL%EF%BC%9ATD%E3%80%81%E4%BC%98%E5%8A%BF%E3%80%81%E4%BF%A1%E4%BB%BB%E5%9F%9F%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<p>与完整 RL 的对照要逐项过。消失的：转移 \\(P\\)、折扣、跨步信用分配、价值函数的自举链。留下的：探索——情境内的动作分布仍要看不见全部奖励才能学好。ε-贪婪（<a href="/llm/exploration-epsilon">探索与利用：ε-贪婪与乐观</a>）与乐观面对不确定性加成，Auer 2002 对 UCB 给出对数级遗憾界：总遗憾只随回合数按对数增长，探索的代价被严格定价。上下文信息的加入不改变这个结构，只把「每个动作一个均值」换成「每个情境学一张动作—奖励表」。</p><p><span class="marginnote">直觉类比：老虎机是一臂只看一台机器的平均回报；上下文 bandit 是每台机器旁边贴着一张「客人画像」——年轻客人在 A 机回报高、常客在 B 机回报高。你每次先看画像（情境 \\(x\\)）再选机器（动作 \\(a\\)），拉完立刻知道输赢（奖励 \\(r\\)），不用等后续剧情，这就是「视界为 1」。</span></p><p><span class="marginnote">Auer 2002 的 UCB1 在随机 bandit 上把期望遗憾压到对数级；温度采样不是这个意义上的探索——它不随证据更新动作分布，也不承诺任何遗憾界。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>价值函数为什么在 bandit 里可有可无，值得说透：完整 RL 里 \\(V\\) 存在是为了在动作后果到来之前预估它；bandit 的后果当场兑现，评估与最优选择合一，回归器就是价值函数。这解释了 bandit 问题里没有 GAE、没有 TD 误差、也没有信任域焦虑——一步之内没有「走太远」的几何意义，<a href="/llm/trust-region-monotone">信任域与单调改进</a>讨论的策略散度失去了载体。</p><p>LLM 的对应由此逐项落位。RLHF 的第一层天然是 bandit：prompt 是情境，整条完成是一个动作，<a href="/llm/reward-model">奖励模型</a>的标量是当场兑现的奖励。序列级 REINFORCE（<a href="/llm/reinforce-llm">REINFORCE / R3</a>）是有意按 bandit 办事：整段 \\(\\log\\pi_\\theta(y\\mid x)\\) 乘同一个 \\((R-b)\\)，放弃 token 级信用，接受随之而来的方差。Best-of-N（<a href="/llm/best-of-n">Best-of-N</a>）是只利用、不学习的 bandit——每一步都从同一个策略抽 \\(N\\) 条、按分取最大，选择不改变下一次的分布。单轮偏好标注（同 prompt 两答选一）更是一个纯 bandit 数据问题：<a href="/llm/llm-decision-view">语言生成作为 MDP</a> 里的时间维在这类数据上根本没被触碰。</p>',6)),(e(),n(o,null,{default:t(()=>[r(i,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20LR%0A%20%20SC%5B%22LLM%20%E8%AE%AD%E7%BB%83%E5%9C%BA%E6%99%AF%22%5D%20--%3E%20Q%7B%22%E5%8A%A8%E4%BD%9C%E6%9C%89%E8%B7%A8%E6%AD%A5%E5%90%8E%E6%9E%9C%E5%90%97%22%7D%0A%20%20Q%20--%3E%7C%22%E6%89%93%E5%88%86%E5%BD%93%E5%9C%BA%E5%85%91%E7%8E%B0%22%7C%20B1%5B%22RLHF%20%E5%8D%95%E8%BD%AE%20%2F%20%E5%81%8F%E5%A5%BD%E6%A0%87%E6%B3%A8%3Cbr%2F%3E%E6%A0%87%E5%87%86%20bandit%22%5D%0A%20%20Q%20--%3E%7C%22%E5%8F%AA%E5%9C%A8%E7%AD%96%E7%95%A5%E5%86%85%E6%8A%BD%E5%A4%9A%E6%AC%A1%22%7C%20B2%5B%22Best-of-N%3Cbr%2F%3E%E5%8F%AA%E5%88%A9%E7%94%A8%E4%B8%8D%E5%AD%A6%E4%B9%A0%E7%9A%84%20bandit%22%5D%0A%20%20Q%20--%3E%7C%22%E5%BC%80%E5%A4%B4%E5%8F%A5%E5%BC%8F%E5%86%B3%E5%AE%9A%E5%90%8E%E6%96%87%E5%BE%97%E5%88%86%22%7C%20B3%5B%22%E4%B8%8D%E6%98%AF%20bandit%3Cbr%2F%3E%E9%9C%80%20token%20%E7%BA%A7%E4%BF%A1%E7%94%A8%E5%88%86%E9%85%8D%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<p>bandit 视角何时不够：同一回合内 token 其实有后果——开头定下的句式决定后面能不能拿到奖励，推理链的前半段决定后半段的对错。这时要把时间结构请回来。<a href="/llm/prm-in-rl-loop">过程奖励进训练环</a>给长链补中间刻度，正是在 bandit 视角上重新架起信用分配；PPO/GRPO 的逐 token 比率则是承认动作不是整条完成、而是每个 token。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>把一切都叫 bandit 会错在哪。其一，遗憾界的假设会被 LLM 场景悄悄破坏：情境分布不因动作改变，而策略更新会改变下一批到达的 prompt（用户会涌向表现好的用法），非平稳性没有进 Auer 的账。其二，温度采样常被当成探索，但它是固定的抽样扰动，不随证据收敛，<a href="/llm/exploration-epsilon">探索与利用：ε-贪婪与乐观</a>的账它认领不了。其三，多步任务（工具链、代码库）动作后果跨回合存在，bandit 只能当近似，硬套会把长程信用错误记到最后一拍上。</p><p><span class="marginnote">术语翻译：「遗憾」（regret）是数学家给「试错学费」起的名字——你每回合选的机器与事后已知最好的机器之间的回报差，累加起来就是遗憾。说 UCB「遗憾按对数增长」，意思是玩得越久、学费摊得越薄；探索不是浪费，是有价格上限的必要投资。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>上下文 bandit 是视界 1 的 MDP：情境、动作、即时奖励，无转移、无折扣、无跨步信用分配。</li><li>策略梯度退化为单项 \\((r-b(x))\\nabla\\log\\pi\\)；动作价值可直接平均，不必自举，致命三要素少一角。</li><li>探索问题完整保留：UCB 的对数遗憾界给探索定价；温度采样不算探索。</li><li>RLHF 的单轮偏好、序列级 REINFORCE、Best-of-N 都是 bandit 视角的合法实例；token 有后果时要把时间维请回来。</li><li>出处：Sutton 与 Barto, <em>Reinforcement Learning: An Introduction</em>, 2018 第 2 章；Auer 等, Finite-time Analysis of the Multiarmed Bandit Problem, 2002。</li></ul>',6))])}const u=d(s,[["render",p]]);export{c as __pageData,u as default};
